package lesson_2;

public class PositiveOrNegativeNumberConsol {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		positiveOrNegativeNumberConsol (-1);
	}

	public static void positiveOrNegativeNumberConsol (int a) {
	
		if (a > 0) {
			System.out.println("положительное число");
		}
		else {
			System.out.println("отрицательное число");
	    }
	}
	
}
